            "name": "api_key_hint_chars",
            "type": "int32",
            "description": "api_key_hint_chars is how many trailing characters of a stored key the read\n surface may echo back, so a person can tell WHICH key is saved without the\n key being retrievable. Config rather than a constant because it is a\n privacy/usability trade a deployment makes, and moving it must not need a\n redeploy. 0 disables the hint entirely.\n\n Capped at 8: a hint long enough to be searched for is not a hint.",
            "default": 4,
            "constraints": [
              "must be \u003e= 0",
              "must be \u003c= 8"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              },
              {
                "rule": "assert_le",
                "target": "field",
                "value_kind": "int",
                "int_value": 8,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "scotty_config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "scotty",
        "description": "Config is delivered by kernel at startup and on every change.",
        "fields": [
          {
            "name": "max_open_tickets",
            "type": "int32",
            "description": "max_open_tickets bounds how many tickets may be open at once, and exists\n for the same reason tasks.Config.max_open_tasks does: to give the service a\n rule that comes from CONFIG rather than from code, so changing it in kernel\n changes behaviour with no redeploy.\n\n NOT a written policy. §2 is explicit that \"an entitlement makes an action\n impossible, a written policy makes it inadvisable\" — a config bound that\n hard-fails a create is neither, it is a resource limit on the service. No\n business rule may be expressed here.",
            "default": 1000
          },
          {
            "name": "max_chain_hops",
            "type": "int32",
            "description": "max_chain_hops is the CIRCUIT BREAKER on AI-mediated negotiation, and it is\n a HOP COUNT, not a duration. A chain's hop count is the number of turns\n taken in it — every Ticket, TicketAdvice and TicketComment sharing a\n chain_id — and when it reaches this bound Scotty stops adding its own\n judgement to that chain. Jody, 2026-08-30: \"it escalates to the human at\n the same level. It just keeps LLMs from getting stuck in a loop.\"\n\n Config for the same reason max_open_tickets is: it is a resource-shaped\n bound on the service, changeable in kernel with no redeploy, and it is NOT\n a written policy — nothing here decides anything about a request.\n\n A wall-clock TTL was proposed for this and explicitly discarded; see\n loopers/schematic/decisions/ticket-ttl-hop-count-circuit-breaker-2026-08-30.md.",
            "default": 20
          },
          {
            "name": "llm_credential",
            "type": "string",
            "description": "llm_credential is the Anthropic API key, fanned out by operator into this\n service's generated bootstrap config under the YAML key \"llm_credential\"\n (see platform/proto/services/operator.proto's Config.llm_credential and\n .llm_credential_services, and operator.yaml's own llm_credential_services\n list, which must include \"scotty\" for the fan-out to reach here). Field\n name and type must match what operator's bootstrap.go writes, or the\n service fails to unmarshal its own generated config.",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "TenantConfig",
  "package": "tenant_config",
  "description": "TenantConfig aggregates per-service tenant configuration slices.\n Field names match service names; field numbers are stable via registry.yaml.",
  "fields": [
    {
      "name": "kernel",
      "type": "message",
      "message": {
        "name": "KernelTenantConfig",
        "package": "credentials",
        "description": "KernelTenantConfig is the per-tenant kernel configuration slice.\n Tacplus auto-generates TenantConfig with this as the kernel field.",
        "fields": [
          {
            "name": "cred_pairs",
            "type": "message",
            "description": "cred_pairs are the tenant's cred_pairs (JWK + entitlements + tenant-relative\n namespaces). They authenticate management RPCs as ordinary C2S identities\n (no P2S). Public keys only — private keys never enter the cluster. The\n creating root registers the tenant's first cred_pair public key via\n kernel.TenantAdmin.SetTenantConfig (bootstrap); nothing is minted or\n delivered server-side. Holders generate their own keypairs off-cluster.",
            "repeated": true,
            "constraints": [
              "maximum size: 256 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "CredPair",
              "package": "credentials",
              "description": "CredPair is a tenant-scoped credential. Public key stored in the tenant's\n KernelTenantConfig slice; private key never leaves the holder. Used to\n authenticate kernel.TenantAdmin RPCs and (downstream) any tenant-scoped\n RPC across the cluster.\n\n A request authenticated by CredPair carries the SPIFFE URI\n `spiffe://\u003cspiffe_prefix\u003e/\u003ctenant_name\u003e/users/cred-pair:\u003cid\u003e`.\n\n `entitlements` must always be a subset of the tenant's ceiling\n (kernel.Constraints.entitlements_ceiling). Enforcement is in\n kernel.TenantAdmin.SetTenantConfig.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "id is a unique identifier for this cred_pair within its owning tenant.",
                  "required": true,
                  "constraints": [
                    "minimum size: 1",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "tenant_name",
                  "type": "string",
                  "description": "tenant_name names the owning tenant — the namespace that `namespaces` are\n relative to. The cluster cred_pair's owner is the root \"/\".",
                  "required": true,
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "public_key",
                  "type": "message",
                  "description": "public_key is the cred_pair's public key, as a JWK. Mint verifies a\n cred_pair-signed proof against it to issue a token.",
                  "required": true,
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "message": {
                    "name": "Jwk",
                    "package": "jwk",
                    "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
                    "fields": [
                      {
                        "name": "kty",
                        "type": "enum",
                        "description": "Kty is the key type parameter (RSA, EC, or OKP)",
                        "enum_values": [
                          {
                            "name": "KEY_TYPE_RSA",
                            "number": 1,
                            "description": "KeyTypeRsa represents an RSA key type"
                          },
                          {
                            "name": "KEY_TYPE_EC",
                            "number": 2,
                            "description": "KeyTypeEc represents an Elliptic Curve key type"
                          },
                          {
                            "name": "KEY_TYPE_OKP",
                            "number": 3,
                            "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
                          }
                        ]
                      },
                      {
                        "name": "alg",
                        "type": "string",
                        "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
                        "required": true,
                        "constraints": [
                          "maximum size: 64 bytes",
                          "minimum size: 1"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 64,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_min_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "kid",
                        "type": "string",
                        "description": "Kid is the key ID used to match keys with signatures",
                        "required": true,
                        "constraints": [
                          "maximum size: 512 bytes",
                          "minimum size: 1"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 512,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_min_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "use",
                        "type": "enum",
                        "description": "Use indicates the intended use of the key (sig for signatures, enc for encryption)",
                        "enum_values": [
                          {
                            "name": "JWK_USE_TYPE_SIG",
                            "number": 1,
                            "description": "JwkUseTypeSig indicates the key is used for digital signatures"
                          },
                          {
                            "name": "JWK_USE_TYPE_ENC",
                            "number": 2,
                            "description": "JwkUseTypeEnc indicates the key is used for encryption"
                          }
                        ]
                      },
                      {
                        "name": "e",
                        "type": "string",
                        "description": "E is the RSA public exponent (base64url encoded without padding)",
                        "constraints": [
                          "must be base64 encoded",
                          "maximum size: 64 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 64,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_base64",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "n",
                        "type": "string",
                        "description": "N is the RSA modulus (base64url encoded without padding)",
                        "constraints": [
                          "must be base64 encoded",
                          "maximum size: 1024 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_base64",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "crv",
                        "type": "string",
                        "description": "Crv is the elliptic curve name (e.g., P-256, P-384, P-521, Ed25519)",
                        "constraints": [
                          "maximum size: 64 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 64,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "x",
                        "type": "string",
                        "description": "X is the x coordinate for EC keys or the public key for OKP (base64url encoded without padding)",
                        "constraints": [
                          "must be base64 encoded",
                          "maximum size: 256 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 256,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_base64",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "y",
                        "type": "string",
                        "description": "Y is the y coordinate for EC keys (base64url encoded without padding, not used for OKP)",
                        "constraints": [
                          "must be base64 encoded",
                          "maximum size: 256 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 256,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_base64",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "exp",
                        "type": "int64",
                        "description": "Exp is the expiration in epoch seconds. This is not part of the JWK spec as the spec does\n not specify how to handle public key expiration.\n When stored in a collection with epoch_expiration, the state store computes TTL = exp - now\n and auto-evicts the entry on expiry."
                      },
                      {
                        "name": "created",
                        "type": "int64",
                        "description": "Created is the Unix epoch timestamp (seconds) when the key was created (optional).\n If set, valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                        "constraints": [
                          "must be \u003e= 1735689600",
                          "must be \u003c= 8045740800"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1735689600,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8045740800,
                            "source": "annotation"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "entitlements",
                  "type": "message",
                  "description": "entitlements this cred_pair holds (⊆ the owning tenant's ceiling), as the\n SAME TokenEntitlements the C2S authorizer checks: the minted cred_pair token\n sets service_entitlements = this directly (uniform with IDP-user tokens).",
                  "message": {
                    "name": "TokenEntitlements",
                    "package": "entitlements",
                    "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
                    "fields": [
                      {
                        "name": "grants",
                        "type": "string",
                        "description": "grants is a flat list of generated grant tokens, e.g. PACKAGE_SERVICE_RPC.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "data_grants",
                        "type": "string",
                        "description": "data_grants is a flat list of generated data-entitlement grant tokens, e.g.\n PACKAGE_RECORD_FIELD. A data grant names what the caller may SEE RAW: a MAY_*\n redact field with a matching grant egresses raw; absent a grant the field gets\n its most-protective default (MAY_REDACT -\u003e REDACT, MAY_ANONYMIZE -\u003e ANONYMIZE).\n Stamped by OPA at token-exchange time alongside grants — an identity property,\n never a request parameter.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "principal_scope",
                        "type": "string",
                        "description": "principal_scope is how wide the caller's authority over PRINCIPALS is, as a\n spec.PrincipalScope enum VALUE NAME (e.g. \"PRINCIPAL_SCOPE_ANY\"). It is the\n claim the generated (spec.owner_default) guard reads to tell an owner acting\n on its own row from a principal whose authority is wider than itself.\n Absent, empty, PRINCIPAL_SCOPE_UNSPECIFIED and PRINCIPAL_SCOPE_SELF_ONLY all\n mean self-scoped: the guard fails closed, so a policy that stamps nothing\n leaves every caller exactly as narrow as it is today.\n Stamped by OPA at token-exchange time alongside grants — an identity\n property, never a request parameter.",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "azp",
                        "type": "string",
                        "description": "azp restricts these entitlements to tokens with a matching authorized party.\n Empty = entitlements apply regardless of azp.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 1024 elements (default)",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1024,
                            "defaulted": true,
                            "unit": "elements",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "namespaces",
                  "type": "string",
                  "description": "namespaces are the authorized namespaces, RELATIVE to the owning tenant\n (e.g. \"default\", \"prod\", or \"*\" for all of the tenant's projects). The\n cred_pair can only act at-or-below these and literally cannot name another\n tenant. The cluster cred_pair is relative to \"/\", so it can span tenants.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 256 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "description",
                  "type": "string",
                  "description": "description is a human-readable label.",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created_at",
                  "type": "message",
                  "description": "created_at is when this credential was created."
                },
                {
                  "name": "expires_at",
                  "type": "message",
                  "description": "expires_at is the optional expiry. Zero value means no expiry."
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
