                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "authorized_services",
            "type": "enum",
            "description": "authorized_services lists services this delegate can request tokens for.\n Values are generated ServiceName enum entries matching service declarations.\n The delegate can always request a token for itself (sub=name).\n Use SERVICE_NAME_ANY to allow all services.",
            "repeated": true,
            "constraints": [
              "maximum size: 64 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "SERVICE_NAME_SENTINEL",
                "number": 5
              },
              {
                "name": "SERVICE_NAME_GATEWAY",
                "number": 7
              },
              {
                "name": "SERVICE_NAME_KERNEL",
                "number": 8
              },
              {
                "name": "SERVICE_NAME_LETSENCRYPT",
                "number": 9
              },
              {
                "name": "SERVICE_NAME_EVENTBUS",
                "number": 18
              },
              {
                "name": "SERVICE_NAME_OAUTH",
                "number": 21
              },
              {
                "name": "SERVICE_NAME_OPA",
                "number": 29
              },
              {
                "name": "SERVICE_NAME_STRATUM",
                "number": 34
              },
              {
                "name": "SERVICE_NAME_KMAKER",
                "number": 49
              },
              {
                "name": "SERVICE_NAME_SAMLSVC",
                "number": 51
              },
              {
                "name": "SERVICE_NAME_MESSAGING",
                "number": 53
              },
              {
                "name": "SERVICE_NAME_SCOTTYAGENT",
                "number": 54
              },
              {
                "name": "SERVICE_NAME_MAILBOX",
                "number": 55
              },
              {
                "name": "SERVICE_NAME_LLMSETTINGS",
                "number": 56
              },
              {
                "name": "SERVICE_NAME_SCOTTY",
                "number": 70
              },
              {
                "name": "SERVICE_NAME_ANY",
                "number": 99
              }
            ]
          },
          {
            "name": "custom_claims",
            "type": "map",
            "description": "custom_claims are static key-value pairs added to every access token\n minted for this delegate. Useful for identity claims (e.g. email).\n Standard JWT claims (sub, iss, aud, exp, iat, azp, nbf, jti, typ,\n parent_sub) are reserved and will be skipped.",
            "repeated": true,
            "constraints": [
              "maximum size: 20 entries",
              "maximum key size: 32768 bytes (default)",
              "maximum value size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 20,
                "unit": "entries",
                "source": "annotation"
              },
              {
                "rule": "default_max_key_size",
                "target": "key",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              },
              {
                "rule": "default_max_value_size",
                "target": "value",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ],
            "map_key_type": "string",
            "map_value_type": "string"
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "fqdn",
      "type": "string",
      "description": "fqdn is the fully qualified domain name for this cluster\n (e.g. \"api.example.com\"). Published to Identity state for\n services like letsencrypt. No default — must be set for production.",
      "constraints": [
        "must be a fully qualified domain name",
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_fqdn",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "issuer",
      "type": "string",
      "description": "issuer is the full issuer URL for tokens minted by this cluster.\n For local development, computed as https://\u003cfqdn\u003e:\u003cport\u003e (port omitted if 443).\n For production behind a load balancer, set explicitly (e.g. \"https://api.example.com\").",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "key_rotation_interval_seconds",
      "type": "int64",
      "description": "key_rotation_interval_seconds is how often the exchanger rotates\n its own signing keys. Default: 24 hours.",
      "default": 86400
    },
    {
      "name": "default_token_expiry_seconds",
      "type": "int64",
      "description": "default_token_expiry_seconds is the default lifetime for issued\n access tokens when the request does not specify an expiry. Default: 1 hour.",
      "default": 3600
    },
    {
      "name": "ca_cert_lifetime_seconds",
      "type": "int64",
      "description": "ca_cert_lifetime_seconds is the lifetime for node CA certificates.\n Default: 31536000 (1 year). Node CA certs are regenerated on restart.",
      "default": 31536000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "access_token_lifetime_seconds",
      "type": "int64",
      "description": "access_token_lifetime_seconds is the default lifetime for user access tokens\n minted via MintToken. Default: 900 (15 minutes).",
      "default": 900,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "refresh_token_lifetime_seconds",
      "type": "int64",
      "description": "refresh_token_lifetime_seconds is the default lifetime for user refresh tokens\n minted via MintToken. Default: 86400 (24 hours).",
      "default": 86400,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "tls_cert_lifetime_seconds",
      "type": "int64",
      "description": "tls_cert_lifetime_seconds is the lifetime for auto-TLS service certificates.\n Kernel sends a renewal request at half-life. Default: 86400 (24 hours).",
      "default": 86400,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_token_lifetime_seconds",
      "type": "int64",
      "description": "max_token_lifetime_seconds is the maximum lifetime kernel will allow for\n any minted token. Requests with exp beyond now + this value are rejected.\n Delegates control their own exp policy within this ceiling.\n Default: 2592000 (30 days).",
      "default": 2592000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "offline_token_lifetime_seconds",
      "type": "int64",
      "description": "offline_token_lifetime_seconds is the default lifetime for Offline Tokens\n (OT) — the long-lived, identity-only tokens persisted on disk by the\n schematic daemon and renewed before half-life. Months, not hours.\n Default: 7776000 (90 days). Exempt from max_token_lifetime_seconds, which\n caps short-lived access/service tokens.",
      "default": 7776000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "root_cred_pairs",
      "type": "message (recursive reference: credentials.CredPair)",
      "description": "root_cred_pairs are the bootstrap admin credentials, rendered into this\n config by the operator from operator.yaml. Each is an ordinary C2S CredPair\n owned by the root namespace; kernel installs them into the root namespace's\n TenantConfig at boot (granting full entitlements) so a holder can sign a\n proof, exchange it via MintClientToken, and provision tenants/projects via\n TenantAdmin. Only the public half is carried here.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "spiffe_trust_domain",
      "type": "string",
      "description": "spiffe_trust_domain is the SPIFFE URI authority: a globally unique instance\n name for this autonomous-system instance (need not be a DNS domain). It must\n not contain '/', a scheme, query, or fragment, and carries no path. Service\n identity is built by the generated sys/spiffe helper as:\n   spiffe://\u003cspiffe_trust_domain\u003e/system/\u003clocation_path...\u003e/services/\u003cservice_label\u003e\n If empty, SPIFFE IDs are not set on issued tokens or X509 URI SANs. Kernel\n copies this (with location_path) into the runtime grpcconfig.Config it seeds\n into ServiceConfigState, so every service shares one trust domain.",
      "default": "local.dev",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "location_path",
      "type": "string",
      "description": "location_path is this deployment's topology path under /system — opaque,\n tag-delimited, slash-separated segments, arity not fixed (e.g.\n \"aws/123456789012/us-east-1a/cluster-7/team-a\"). Segments follow the SPIFFE\n segment grammar and must not be reserved tags. Supplied by the operator from\n runtime config (where the cluster runs); it is not a token claim. May be\n empty (no topology tiers).",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "health_probe_port",
      "type": "int32",
      "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kernel's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kernel.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
      "default": 8444
    },
    {
      "name": "grants",
      "type": "message",
      "description": "grants seeds the standing delegation Grant catalog at boot, loaded into\n the live grants store the same way delegates (above) are — there is no\n runtime grant-creation RPC yet, so this is the only way a Grant exists\n today.",
      "repeated": true,
      "constraints": [
        "maximum size: 4096 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4096,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Grant",
        "package": "kernel",
        "description": "Grant is a standing delegation: a user authorizes a delegate (an intermediary\n service, e.g. an agent acting on a schedule) to act on their behalf later,\n asynchronously. Kernel\n stores the GRANT, never a minted token — the delegate holds only `id`.\n\n On use the delegate presents its own S2S identity plus `id`; kernel replays\n `claims` into OPA fresh (the same EntitlementEvalInput shape\n `IdentityServiceImpl.buildClaimsStruct` already builds from a token payload),\n intersects the result with `authorized_scope`, and mints a short-lived token\n (sub=subject, act=delegate_name, azp=kernel — kernel mints Grant tokens\n directly, so azp is always the closed-enum `kernel` value; the delegate name\n goes on the `act` claim instead). Fresh OPA gives \"cannot exceed the user's\n current authority\"; the recorded scope gives \"the user downscoped it\". Nothing\n is snapshotted that can go stale except the claims themselves — which catches\n policy changes, never IDP changes.\n\n This message is carried in KernelDiskState and mutated at runtime by\n Mint.RevokeGrant (revoked_at_ms) only; there is no create/list RPC yet — the\n catalog is still seeded from Config.grants at boot.\n\n PROVISIONAL: this field set is a prerequisite storage layer built ahead of,\n not instead of, the design conversation with the maintainer. What is settled:\n id, delegate_name, subject, authorized_scope, claims, created_at_ms,\n expires_at_ms, revoked_at_ms. NOT settled: how the system learns a user's IDP\n claims changed or the user was deleted — claim-provenance and epoch are still\n open and may add fields here.",
        "fields": [
          {
            "name": "id",
            "type": "string",
            "description": "id is the opaque grant identifier the delegate holds and presents. Unique\n across the cluster.",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "delegate_name",
            "type": "string",
            "description": "delegate_name is the Delegate.name of the intermediary holding this grant.\n It becomes the minted token's act claim (azp on a Grant mint is always\n kernel — see the message comment above).",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "subject",
            "type": "string",
            "description": "subject is the user this grant acts for — the sub of the token that will be\n minted, and the identity whose claims were recorded below.",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "authorized_scope",
            "type": "message (recursive reference: entitlements.TokenEntitlements)",
            "description": "authorized_scope is the per-service scope the user recorded at consent time.\n Every mint intersects the fresh OPA result with this, so the grant can only\n ever narrow the user's live authority, never widen it."
          },
          {
            "name": "claims",
            "type": "message",
            "description": "claims are the user's IDP claims as captured at consent time, in the same\n google.protobuf.Struct shape that userentitlements.EntitlementEvalInput.claims\n takes, so they can be replayed into OPA verbatim."
          },
          {
            "name": "created_at_ms",
            "type": "int64",
            "description": "created_at_ms is the consent time, epoch milliseconds.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "expires_at_ms",
            "type": "int64",
            "description": "expires_at_ms is when the grant itself stops being usable, epoch\n milliseconds. 0 means no expiry (revocation only).",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "revoked_at_ms",
            "type": "int64",
            "description": "revoked_at_ms is when the grant was revoked via Mint.RevokeGrant, epoch\n milliseconds. 0 means not revoked. A revoked grant is MARKED, never\n deleted, so the record remains as an audit trail of the delegation that\n existed and when it was withdrawn. Every mint from the grant and every\n later exchange of a token minted from it is denied once this is set\n (IdentityServiceImpl.assertGrantStillActive), so revocation kills\n already-minted derived tokens within one request.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "ratis_listener",
      "type": "message (recursive reference: host.Host)",
      "description": "ratis_listener is the bind address for the embedded Apache Ratis peer\n group that backs the FencedLock service. Kernel is the only service in the\n fleet that runs Ratis. Peers are derived from `members` above (same hosts,\n this port) so lock membership tracks cluster membership and there is no\n second topology to keep in sync. Default port 5002 — the next one after\n hazelcast_listener's 5001."
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "ConfigState",
  "package": "kernel",
  "description": "ConfigState is the kernel-hosted persistence boundary for tenants/projects.\n Kernel writes it and persists it; other services watch their per-tenant/\n per-project config slice via the export: true wire.",
  "fields": [
    {
      "name": "tenants",
      "type": "message",
      "description": "tenants is the list of all tenant records, keyed by tenant.name.",
      "repeated": true,
      "constraints": [
        "maximum size: 4096 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4096,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Tenant",
        "package": "kernel",
        "description": "Tenant is the core identity record for a tenant in the cluster.\n `name` is unique, immutable, and becomes the tenant's SPIFFE segment:\n   spiffe://\u003ctrust-domain\u003e/tenants/\u003cname\u003e/...",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "status",
            "type": "enum",
            "enum_values": [
              {
                "name": "TENANT_STATUS_ACTIVE",
                "number": 1
              },
              {
                "name": "TENANT_STATUS_SUSPENDED",
                "number": 2
              }
            ]
          },
          {
            "name": "constraints",
            "type": "message",
            "description": "constraints is the ancestor-set limits (entitlements ceiling now; domain\n later). Set at creation; mutable only by an ancestor.",
            "message": {
              "name": "Constraints",
              "package": "kernel",
              "description": "Constraints are the limits an ancestor places on a tenant. They live on the\n Tenant record (set at CreateTenant), are mutable only by an ancestor, and are\n immutable to the tenant itself — so the tenant genuinely cannot raise its own\n limits. Validated on CreateTenant and SetTenantConfig.\n\n (The \"min-admin-credential\" rule — config must always contain \u003e=1 cred_pair\n entitled to administer the tenant — is NOT a field here: it is an always-on\n invariant enforced in the SetTenantConfig validation path, satisfiable by\n create-and-discard. It is not an ancestor toggle.)",
              "fields": [
