{
  "name": "Grant",
  "package": "kernel",
  "description": "Grant is a standing delegation: a user authorizes a delegate (an intermediary\n service, e.g. an agent acting on a schedule) to act on their behalf later,\n asynchronously. Kernel\n stores the GRANT, never a minted token — the delegate holds only `id`.\n\n On use the delegate presents its own S2S identity plus `id`; kernel replays\n `claims` into OPA fresh (the same EntitlementEvalInput shape\n `IdentityServiceImpl.buildClaimsStruct` already builds from a token payload),\n intersects the result with `authorized_scope`, and mints a short-lived token\n (sub=subject, act=delegate_name, azp=kernel — kernel mints Grant tokens\n directly, so azp is always the closed-enum `kernel` value; the delegate name\n goes on the `act` claim instead). Fresh OPA gives \"cannot exceed the user's\n current authority\"; the recorded scope gives \"the user downscoped it\". Nothing\n is snapshotted that can go stale except the claims themselves — which catches\n policy changes, never IDP changes.\n\n This message is carried in KernelDiskState and mutated at runtime by\n Mint.RevokeGrant (revoked_at_ms) only; there is no create/list RPC yet — the\n catalog is still seeded from Config.grants at boot.\n\n PROVISIONAL: this field set is a prerequisite storage layer built ahead of,\n not instead of, the design conversation with the maintainer. What is settled:\n id, delegate_name, subject, authorized_scope, claims, created_at_ms,\n expires_at_ms, revoked_at_ms. NOT settled: how the system learns a user's IDP\n claims changed or the user was deleted — claim-provenance and epoch are still\n open and may add fields here.",
  "fields": [
    {
      "name": "id",
      "type": "string",
      "description": "id is the opaque grant identifier the delegate holds and presents. Unique\n across the cluster.",
      "required": true,
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "delegate_name",
      "type": "string",
      "description": "delegate_name is the Delegate.name of the intermediary holding this grant.\n It becomes the minted token's act claim (azp on a Grant mint is always\n kernel — see the message comment above).",
      "required": true,
      "constraints": [
        "maximum size: 512 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 512,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "subject",
      "type": "string",
      "description": "subject is the user this grant acts for — the sub of the token that will be\n minted, and the identity whose claims were recorded below.",
      "required": true,
      "constraints": [
        "maximum size: 512 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 512,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "authorized_scope",
      "type": "message",
      "description": "authorized_scope is the per-service scope the user recorded at consent time.\n Every mint intersects the fresh OPA result with this, so the grant can only\n ever narrow the user's live authority, never widen it.",
      "message": {
        "name": "TokenEntitlements",
        "package": "entitlements",
        "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
        "fields": [
          {
            "name": "grants",
            "type": "string",
            "description": "grants is a flat list of generated grant tokens, e.g. PACKAGE_SERVICE_RPC.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "data_grants",
            "type": "string",
            "description": "data_grants is a flat list of generated data-entitlement grant tokens, e.g.\n PACKAGE_RECORD_FIELD. A data grant names what the caller may SEE RAW: a MAY_*\n redact field with a matching grant egresses raw; absent a grant the field gets\n its most-protective default (MAY_REDACT -\u003e REDACT, MAY_ANONYMIZE -\u003e ANONYMIZE).\n Stamped by OPA at token-exchange time alongside grants — an identity property,\n never a request parameter.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "principal_scope",
            "type": "string",
            "description": "principal_scope is how wide the caller's authority over PRINCIPALS is, as a\n spec.PrincipalScope enum VALUE NAME (e.g. \"PRINCIPAL_SCOPE_ANY\"). It is the\n claim the generated (spec.owner_default) guard reads to tell an owner acting\n on its own row from a principal whose authority is wider than itself.\n Absent, empty, PRINCIPAL_SCOPE_UNSPECIFIED and PRINCIPAL_SCOPE_SELF_ONLY all\n mean self-scoped: the guard fails closed, so a policy that stamps nothing\n leaves every caller exactly as narrow as it is today.\n Stamped by OPA at token-exchange time alongside grants — an identity\n property, never a request parameter.",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "azp",
            "type": "string",
            "description": "azp restricts these entitlements to tokens with a matching authorized party.\n Empty = entitlements apply regardless of azp.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "claims",
      "type": "message",
      "description": "claims are the user's IDP claims as captured at consent time, in the same\n google.protobuf.Struct shape that userentitlements.EntitlementEvalInput.claims\n takes, so they can be replayed into OPA verbatim."
    },
    {
      "name": "created_at_ms",
      "type": "int64",
      "description": "created_at_ms is the consent time, epoch milliseconds.",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "expires_at_ms",
      "type": "int64",
      "description": "expires_at_ms is when the grant itself stops being usable, epoch\n milliseconds. 0 means no expiry (revocation only).",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "revoked_at_ms",
      "type": "int64",
      "description": "revoked_at_ms is when the grant was revoked via Mint.RevokeGrant, epoch\n milliseconds. 0 means not revoked. A revoked grant is MARKED, never\n deleted, so the record remains as an audit trail of the delegation that\n existed and when it was withdrawn. Every mint from the grant and every\n later exchange of a token minted from it is denied once this is set\n (IdentityServiceImpl.assertGrantStillActive), so revocation kills\n already-minted derived tokens within one request.",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
