                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "expires_at_ms",
            "type": "int64",
            "description": "expires_at_ms is when the grant itself stops being usable, epoch\n milliseconds. 0 means no expiry (revocation only).",
            "constraints": [
