{
  "name": "Config",
  "package": "mailbox",
  "description": "Config is delivered by kernel at startup and on every change.",
  "fields": [
    {
      "name": "sweep_interval_seconds",
      "type": "int32",
      "description": "sweep_interval_seconds is how often the eviction-eligibility sweep runs.\n\n The sweep is a RECONCILER, not the primary path: UpdateHeldMail marks a row\n eligible inline when it retrieves it. The sweep exists because that inline\n mark can be missed — a publish that hit backpressure, or a row retrieved by\n an instance that died before the publish landed — and because a non-zero\n retrieved_grace_seconds below defers the mark by construction. Held in\n config rather than as a constant for the same reason\n messaging.Config.max_recipients is: changing it in kernel must change\n behaviour with no redeploy.",
      "default": 300,
      "constraints": [
        "must be \u003e= 10",
        "must be \u003c= 86400"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 10,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 86400,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "retrieved_grace_seconds",
      "type": "int32",
      "description": "retrieved_grace_seconds is how long after retrieval a row stays\n NEVER-evict before the sweep marks it WINDOW.\n\n Zero — the default — is the decision doc's ruling taken literally:\n \"retrieved_at_ms is the point item 4's eviction eligibility starts counting\n from\". Marking at grace 0 makes the row's `(spec.store_epoch)`, which is\n what the residency window is measured against, equal to the retrieval\n instant, so the window counts from retrieval and from nothing else.\n\n It is a knob rather than a constant because a client that acks and then\n immediately re-reads is a real pattern, and a non-zero grace keeps the row\n resident across that gap. It can never make an UNRETRIEVED row evictable:\n the sweep's predicate is status == RETRIEVED before it is anything else.",
      "default": 0,
      "constraints": [
        "must be \u003e= 0",
        "must be \u003c= 604800"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 604800,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
