            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "token_audience",
            "type": "string",
            "description": "token_audience is the required Kubernetes TokenReview audience.",
            "default": "kmaker",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "kernel_service_accounts",
            "type": "message",
            "description": "kernel_service_accounts are Kubernetes service accounts allowed to request\n kernel certificates. Empty means namespace=schematic, name=kernel.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "KernelServiceAccount",
              "package": "kmaker",
              "fields": [
                {
                  "name": "namespace",
                  "type": "string",
                  "required": true,
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "name",
                  "type": "string",
                  "required": true,
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "kernel_cert_lifetime_seconds",
            "type": "int64",
            "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
            "default": 86400,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "tls",
            "type": "message (recursive reference: x509.X509CertChain)",
            "description": "tls is the optional serving certificate for kmaker's own gRPC listener.\n When unset, kmaker starts without transport TLS for local/dev only."
          },
          {
            "name": "health_probe_port",
            "type": "int32",
            "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kmaker's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kmaker.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
            "default": 8444
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "llm_credential",
      "type": "string",
      "description": "llm_credential is a shared secret (e.g. an Anthropic API key) fanned out\n into the generated bootstrap config of every app service named in\n llm_credential_services, under the YAML key \"llm_credential\" — so it is\n configured once here rather than duplicated per app service. The\n receiving app service's own Config must declare a matching field. Keep\n this out of version control — store in crypto.yaml.",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "llm_credential_services",
      "type": "string",
      "description": "llm_credential_services names the app services (by AppServiceNames key)\n that should receive llm_credential in their generated bootstrap config.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements",
        "maximum element size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        },
        {
          "rule": "default_max_element_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "MapEmpty",
