{
  "name": "OperatorConfigState",
  "package": "operator",
  "description": "OperatorConfigState is the state boundary for operator service configuration.\n Auto-injected by tacplus from (spec.grpc_config) annotation.",
  "fields": [
    {
      "name": "config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "operator",
        "description": "OperatorConfig is the top-level operator configuration.\n\n Lifecycle:\n   1. operator init ca                   — generate root CA → crypto.yaml\n   2. operator init cluster --ca \u003cpath\u003e  — generate cluster PKI + write operator.yaml\n   3. operator                           — run (IN_CLUSTER) or generate charts (GENERATE_ONLY)\n\n When deployed to Kubernetes:\n   operator.yaml  → ConfigMap  (schematic-operator-config)\n   crypto.yaml    → Secret     (schematic-operator-crypto)\n Both are mounted and merged by the operator at startup.",
        "fields": [
          {
            "name": "mode",
            "type": "enum",
            "description": "How the operator runs.",
            "enum_values": [
              {
                "name": "IN_CLUSTER",
                "number": 0,
                "description": "IN_CLUSTER is the default: the operator runs inside Kubernetes and\n continuously reconciles the desired cluster state by managing Helm releases.\n gateway_nodes is automatically set to the number of schedulable nodes."
              },
              {
                "name": "GENERATE_ONLY",
                "number": 1,
                "description": "GENERATE_ONLY: one-shot CLI mode. Generates Helm charts, writes them to\n output_dir, and exits. Does not communicate with the Kubernetes API."
              }
            ]
          },
          {
            "name": "fqdn",
            "type": "string",
            "description": "Public FQDN for the cluster (e.g. \"api.example.com\").",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "port",
            "type": "int32",
            "description": "HTTPS gateway port. Default 443 for production; 8443 for local testing.",
            "default": 443
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "Kubernetes namespace to deploy all schematic services into.",
            "default": "schematic",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "topology",
            "type": "message",
            "description": "Service replica topology.",
            "message": {
              "name": "Topology",
              "package": "operator",
              "description": "Topology declares the desired replica count for each service.\n\n gateway_nodes is special: when set to 0 and mode = IN_CLUSTER, the operator\n automatically sets it to the number of schedulable Kubernetes nodes at each\n reconciliation cycle (one gateway per node). When mode = GENERATE_ONLY,\n gateway_nodes must be set explicitly.",
              "fields": [
                {
                  "name": "kernel_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "sentinel_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "eventbus_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "gateway_nodes",
                  "type": "int32",
                  "description": "Set to 0 to auto-derive from schedulable node count (IN_CLUSTER only).\n When enabled proxy services (anthropic, openai, gitlab, github) also\n scale to one replica per gateway node."
                },
                {
                  "name": "oauth_nodes",
                  "type": "int32",
                  "description": "oauth_nodes is used when optional_services.oauth = true (default).",
                  "default": 3
                },
                {
                  "name": "opa_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "stratum_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "saml_nodes",
                  "type": "int32",
                  "description": "saml_nodes is used when optional_services.saml = true.",
                  "default": 3
                },
                {
                  "name": "kmaker_nodes",
                  "type": "int32",
                  "description": "kmaker_nodes is the number of bootstrap certificate authority replicas.\n Kernel instances contact kmaker with Kubernetes projected service account\n tokens to obtain kernel certificates before kernel itself is available.",
                  "default": 3
                },
                {
                  "name": "echo_nodes",
                  "type": "int32",
                  "description": "echo_nodes is used when optional_services.echo = true.\n Defaults to 1 rather than 3: the sample service is stateless and exists to\n be poked at, so a second replica proves nothing and costs a pod.",
                  "default": 1
                },
                {
                  "name": "app_services",
                  "type": "map",
                  "description": "app_services declares replica counts for services that are NOT part of the\n platform: an application's own services, defined in the application's proto\n repo and merged into the build.\n\n Every field above is a PLATFORM service with a fixed field number. That is\n fine for the platform, whose service set is what \"the platform\" means — but\n it made the platform unable to host anything else. An application could not\n declare a service without editing this file, and proto3 gives no way to add\n a field to a message from another repo, so \"schematic is reusable\" was not\n true: echo, a sample service, had to take field 17 here to be deployable.\n\n Keyed by service name, so an app adds a service by naming it in its own\n config and this file never changes. Presence with a count \u003e 0 IS the\n enablement — an app service needs no parallel optional_services flag.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 64 entries",
                    "maximum key size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 64,
                      "unit": "entries",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_key_size",
                      "target": "key",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ],
                  "map_key_type": "string",
                  "map_value_type": "int32"
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "tls",
            "type": "message",
            "description": "TLS configuration — letsencrypt or custom CA.\n Validation: if tls.letsencrypt = false, tls.ca must be set.",
            "message": {
              "name": "TLSConfig",
              "package": "operator",
              "description": "TLSConfig controls how edge-facing TLS certificates are obtained.\n When letsencrypt = true, the operator deploys one letsencrypt service replica.",
              "fields": [
                {
                  "name": "letsencrypt",
                  "type": "bool",
                  "description": "When true, Let's Encrypt is used for edge TLS and one letsencrypt service\n replica is deployed. The gateway must be reachable on port 443 from the\n public internet.\n When false, ca must be populated with a valid CA chain."
                },
                {
                  "name": "ca",
                  "type": "message",
                  "description": "Custom CA chain for edge TLS certificates.\n Required when letsencrypt = false. Ignored when letsencrypt = true.",
                  "message": {
                    "name": "X509CertChain",
                    "package": "x509",
                    "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
                    "fields": [
                      {
                        "name": "chain",
                        "type": "message",
                        "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 8 elements",
                          "minimum size: 1"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8,
                            "unit": "elements",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_min_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1,
                            "unit": "elements",
                            "source": "annotation"
                          }
                        ],
                        "message": {
                          "name": "X509Cert",
                          "package": "x509",
                          "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
                          "fields": [
                            {
                              "name": "id",
                              "type": "string",
                              "description": "Id is a unique identifier for the certificate",
                              "constraints": [
                                "maximum size: 256 bytes"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 256,
                                  "unit": "bytes",
                                  "source": "annotation"
                                }
                              ]
                            },
                            {
                              "name": "base64",
                              "type": "string",
                              "description": "Base64 contains the base64url-encoded PEM certificate block",
                              "required": true,
                              "constraints": [
                                "must be base64 encoded",
                                "maximum size: 16384 bytes"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 16384,
                                  "unit": "bytes",
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_base64",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                }
