      "constraints": [
        "maximum size: 64 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        }
