{
  "name": "Config",
  "package": "scottyagent",
  "description": "Config is delivered by kernel at startup and on every change.",
  "fields": [
    {
      "name": "lock_acquire_attempts",
      "type": "int32",
      "description": "lock_acquire_attempts bounds how many times a cycle retries a contended\n per-user lock before giving the record back to the queue.\n\n kernel.FencedLock.Acquire is NON-BLOCKING — a key held by a different\n holder returns granted=false rather than parking the call — so a contended\n acquire is a poll, and something has to bound the polling. Giving up is not\n a failure: the record has not been ACKed, so it is redelivered, and by then\n the instance that held the lock has finished the cycle that would have\n absorbed it anyway.\n\n Config rather than a constant for the same reason messaging's\n max_recipients is: contention is a property of the deployment, and changing\n it must not need a redeploy.",
      "default": 5,
      "constraints": [
        "must be \u003e= 1",
        "must be \u003c= 100"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 100,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "lock_acquire_backoff_ms",
      "type": "int32",
      "description": "lock_acquire_backoff_ms is the wait between those attempts.",
      "default": 200,
      "constraints": [
        "must be \u003e= 1",
        "must be \u003c= 60000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 60000,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_events_per_cycle",
      "type": "int32",
      "description": "max_events_per_cycle bounds the AGGREGATION. Multiple events landing for\n one user while a cycle is running are drained into that cycle rather than\n starting a cycle each — \"they are aggregated and processed together rather\n than firing one loop per event\", per the design record. This is the ceiling\n on one cycle's drain, so a burst cannot buy unbounded work with one lock\n hold; the remainder is picked up by the next cycle.\n\n It must not exceed AgentCycle.woke_for's assert_max_size (256), which is\n the hard edge on how many wake events one cycle row can record.",
