              "must be a valid hostname or IP address",
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_host",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "port",
            "type": "int32",
            "description": "Port number (1-65535).",
            "constraints": [
              "must be a valid network port (1-65535)"
