      "description": "Composite key: \"service:fleetwood@uuid\" — set by server from token claims",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "service_id",
      "type": "string",
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "instance_id",
      "type": "string",
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "grpc_endpoint",
      "type": "message",
      "description": "Reachability",
      "message": {
        "name": "Host",
        "package": "host",
        "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
        "fields": [
          {
