            "filter_mode": "eq"
          },
          {
            "name": "recipients",
            "type": "string",
            "description": "recipients is the full To: line — every recipient of the submission, the\n SAME list on all N deliveries. `recipient` above says which one this row is\n for; this says who else got it.\n\n Carrying it is not redundancy. Without it a recipient cannot see who else\n was addressed, which is information the sender chose to disclose by\n addressing them together — the same reason a To: header exists and a Bcc:\n one does not. (This file models no Bcc; nothing has asked for one.)\n\n Bounded at 256 to match Config.max_recipients' ceiling above.",
            "repeated": true,
            "constraints": [
              "maximum size: 256 elements",
              "maximum element size: 32768 bytes (default)"
