            "name": "request_id",
            "type": "string",
            "description": "request_id is the JOIN KEY to the accounting plane — the same value\n accountingrecord.AccountingRecord carries under the same name with the same\n EQ query_field, so \"which accounting rows belong to the request that sent\n this message\" is one predicate asked of two record types.\n\n Empty is legitimate: a call with no authenticated Caller has none to read.",
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
