            "filter_mode": "eq"
          },
          {
            "name": "sent_at_ms",
            "type": "int64",
            "description": "sent_at_ms is the business clock — when the sender submitted — and the\n RANGE criterion, because \"my messages from last week\" is the question a\n mailbox asks. It is what retention above measures age from.\n\n Identical across all N deliveries of one submission: they were one act.",
            "filter_mode": "range"
          },
          {
