      "type": "message",
      "message": {
        "name": "MailboxEntry",
        "package": "mailbox",
        "description": "MailboxEntry is ONE DELIVERY'S mailbox state, keyed by the SAME delivery_id\n as the `messaging.Message` it tracks.\n\n Joinable by identity, not by a second lookup: an entry and its message share\n a key, so \"fetch the body of the mail I was just told about\" is one Message\n read with an id the client already holds.\n\n IT HOLDS NO BODY. `messaging.Message.text` is never copied here — that is the\n decision doc's rejected alternative (\"Mailbox stores full message content\"),\n and it stands. What IS carried is the inbox SUMMARY LINE the doc's own\n ListHeldMail spec enumerates (sender, subject, sent_at_ms): a mail client\n renders a list before anything is opened, and those three fields are the only\n way to serve that list without a second round trip per row. A summary line is\n not a second copy of the message, and the field that would make it one —\n `text` — is absent, as are `recipients` and `ticket_id`.",
        "fields": [
          {
            "name": "delivery_id",
            "type": "string",
            "description": "delivery_id is the record key and messaging.Message.delivery_id verbatim.\n Bounded identically (512) — a shorter bound here would silently drop the\n deliveries whose recipient subject is long.",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "message_id",
            "type": "string",
            "description": "message_id groups the N entries of one submission, the same way it groups\n the N Messages. EQ-filterable for the same reason it is there.",
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "recipient",
            "type": "string",
            "description": "recipient is whose mailbox this is, and the ROW'S OWNING PRINCIPAL — the\n same field, carrying the same annotation, as messaging.Message.recipient.\n The generated egress filter holds a caller's reads to their own rows, so\n ListHeldMail cannot return one person's mail to another even if this\n service's own predicate were wrong.\n\n spiffe_id below is the record's declared owner but is the PUBLISHER —\n mailbox's own service identity, stamped by eventbus — so it is the wrong\n field to filter a user's reads on, exactly as it is on Message.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "status",
            "type": "enum",
            "constraint_infos": [
              {
                "rule": "assert_enum_defined",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "MAILBOX_ENTRY_STATUS_HELD",
                "number": 1,
                "description": "HELD: the delivery arrived on the topic and nobody has pulled it. The row\n must not be evicted in this state at any age — an unread message aging out\n defeats the entire point of a mailbox."
              },
              {
                "name": "MAILBOX_ENTRY_STATUS_RETRIEVED",
                "number": 2,
                "description": "RETRIEVED: the recipient acknowledged pulling it. This is what starts\n eviction eligibility, and nothing else does."
              }
            ]
          },
          {
            "name": "held_since_ms",
            "type": "int64",
            "description": "held_since_ms is when this consumer group's copy landed — the residency\n clock in the doc's phrasing, and the timestamp retention above measures\n from. It is NOT what eviction eligibility counts from; see retrieved_at_ms.\n\n RANGE-filterable because \"what has been sitting in my mailbox since last\n week\" is a question about this field.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ],
            "filter_mode": "range"
          },
          {
            "name": "retrieved_at_ms",
            "type": "int64",
            "description": "retrieved_at_ms is unset until retrieved, and is the point eviction\n eligibility starts counting from. The decision doc rejects held_since_ms\n for this in as many words: \"a message nobody has pulled yet must not be\n evicted just because it is old.\"",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "sender",
            "type": "string",
            "description": "sender is messaging.Message.sender — the authenticated principal that sent\n it, never a caller-written string on either side.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "subject",
            "type": "string",
            "description": "subject is the subject line. Bounded identically to Message.subject.",
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "sent_at_ms",
            "type": "int64",
            "description": "sent_at_ms is the sender's clock, carried through so an inbox can sort by\n when a message was SENT rather than by when this consumer group happened to\n process it. The two differ by broker latency and by any replay.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "ejectionable",
            "type": "enum",
            "description": "ejectionable is item 4's marker and this record's whole reason to exist —\n the first per-row use of it in the fleet.\n\n The values are not decoration and are not derivable from `status` by the\n store: the store does not know what HELD means, and UNSPECIFIED is defined\n as never-evict precisely so a marker an author forgets keeps the row.\n\n   HELD      -\u003e EJECTIONABLE_NEVER   (explicitly, not left at UNSPECIFIED:\n                the row is stating a policy, not omitting one)\n   RETRIEVED -\u003e EJECTIONABLE_WINDOW  (set by UpdateHeldMail inline, or by\n                the sweep when a grace period deferred it)\n\n WHAT \"EVICT\" DOES, stated plainly because the decision doc left it open:\n it evicts the row FROM MEMORY. It does not delete it. `Residency`'s own\n definition — \"a warm row evicted from memory is still complete and\n queryable on disk\" — is the semantics, and deletion is retention's job\n above, ninety days from arrival. There is deliberately no EVICTED status\n and no delete path here: a status this service wrote would be a claim about\n the store's memory that this service cannot observe.",
            "enum_values": [
              {
                "name": "EJECTIONABLE_NEVER",
                "number": 1,
                "description": "NEVER: the residency window does not apply to this row. It stays resident\n for as long as the type's rows are retained at all. The explicit spelling\n of an absent value, the same way RetentionPolicy.forever is."
              },
              {
                "name": "EJECTIONABLE_WINDOW",
                "number": 2,
                "description": "WINDOW: the residency window applies to this row as declared — it is\n evicted from memory once its (spec.store_epoch) is older than the window,\n and served from disk thereafter."
              }
            ]
          },
          {
            "name": "store_epoch_ms",
            "type": "int64",
            "description": "store_epoch_ms is the row's LAST WRITE, stamped by the generated wrapper\n and never by this service. It is what the residency window is actually\n measured against, which is why marking a row WINDOW is a WRITE: the mark\n and the clock it starts are the same event.\n\n RANGE per (spec.store_epoch)'s own contract — it is the predicate a\n two-leg memory/disk query partitions on.",
            "filter_mode": "range"
          },
          {
            "name": "spiffe_id",
            "type": "string",
            "description": "spiffe_id is the record owner, and the name is LOAD-BEARING: eventbus's\n topic discovery matches the literal field name \"spiffe_id\" of string type\n when deciding which topics get publisher-identity stamping.\n\n It holds MAILBOX'S OWN service identity — this service is the publisher.\n `recipient` above is where the person is.",
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "namespace is the row's owning TENANT, by EXACT string equality against the\n caller's namespace claim. MANDATORY: tacplus fails generation for any\n (spec.record) declaring no such field, on the reasoning that the record\n nobody remembered to annotate is exactly the one that leaks.\n\n Its value is copied from the Message that produced this entry rather than\n resolved again: the tenant of a mailbox entry IS the tenant of the delivery\n it tracks, and re-deriving it from mailbox's own service token would stamp\n the SERVICE's tenant onto a USER's row.\n\n Not a (spec.query_field): the field exists to be the egress boundary, and a\n boundary a caller can name in a predicate is not one.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
