{
  "name": "SampleAgentSessionStateResponse",
  "package": "query",
  "fields": [
    {
      "name": "items",
      "type": "message",
      "repeated": true,
      "constraints": [
        "maximum size: 1024 elements (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "defaulted": true,
          "unit": "elements",
          "source": "default_bound"
        }
      ],
      "message": {
        "name": "AgentSessionState",
        "package": "agentsensor",
        "description": "AgentSessionState is the CURRENT state of one coding-agent session: one row\n per session, rewritten in place every time the session moves.\n\n It exists because the fleet had no mutable warm record and two properties of\n the warm tier are only observable on one. AgentEvent (hot) and AccountingRecord\n (warm, append-only) are both write-once by their own nature — an event and a\n completed RPC have no later state — so nothing exercised the store epoch\n REFRESHING, which is the whole reason the epoch is a last-write clock rather\n than a creation stamp.\n\n A session is the natural carrier for that: it is open for as long as the agent\n is working, its status and counters change while it is open, and once it has\n ended the row is a historical record that ages out of memory exactly like an\n accounting row. Both halves of the warm window apply to it, and unlike the two\n records above it moves while it is resident.\n\n There is no row-mutating RPC and there is not meant to be one: rows reach the\n store by EventBus publish, so an UPDATE is a republish of the same session_id.\n The generated wrapper restamps store_epoch_ms on that republish, which is what\n puts the row back inside the residency window.",
        "fields": [
          {
            "name": "session_id",
            "type": "string",
            "description": "session_id is the record key: one row per session, not one per transition.",
            "required": true,
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "spiffe_id",
            "type": "string",
            "description": "spiffe_id is the record owner — the acting principal's SUBJECT SPIFFE ID,\n stamped by EventBus from the caller's verified token, exactly as on\n AgentEvent. The literal field name is load-bearing for that stamping.",
            "constraints": [
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              }
            ],
            "filter_mode": "eq"
          },
          {
            "name": "started_at_ms",
            "type": "int64",
            "description": "started_at_ms is the session's business clock, fixed at the first publish and\n NOT rewritten afterwards. It is what retention above measures age from.\n\n The contrast with store_epoch_ms below is the point of this record: on an\n append-only row the two clocks are written together and never diverge, so\n nothing could tell them apart. Here they diverge on every update.",
            "constraints": [
              "must be \u003e 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_gt",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ],
            "filter_mode": "range"
          },
          {
            "name": "status",
            "type": "enum",
            "description": "status is the session's current state — the mutable field an update carries.",
            "constraint_infos": [
              {
                "rule": "assert_enum_defined",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "SESSION_STATUS_ACTIVE",
                "number": 1
              },
              {
                "name": "SESSION_STATUS_IDLE",
                "number": 2
              },
              {
                "name": "SESSION_STATUS_ENDED",
                "number": 3
              }
            ]
          },
          {
            "name": "tool_use_count",
            "type": "int32",
            "description": "tool_use_count is how many tool invocations the session has made so far.\n Monotonic, but rewritten in place: the row holds the running total, not one\n row per increment.",
            "constraints": [
              "must be \u003e= 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
